   221	                                    boolean isWarehouseStorage, Xjt45RequestDto paymentRequest) {
   222	        try {
   223	
   224	            if (buyer == null) {
   225	                throw new Xwn18Exception("구매자 정보가 없습니다.");
   226	            }
   227	            if (saleBid == null) {
   228	                throw new Xbk76Exception("판매 입찰 정보가 없습니다.");
   229	            }
   230	            if (addressId == null) {
