   232	            }
   233	            if (paymentRequest == null) {
   234	                throw new Xtv55Exception("결제 정보가 없습니다.");
   235	            }
   236	
   237	
   238	            Xms98ResponseDto address = addressQueryService.getAddress(buyer.getEmail(), addressId);
   239	
   240	
   241	            Xhq12 order = Xhq12.builder()
   242	                    .user(buyer)
   243	                    .totalAmount(saleBid.getBidPrice())
   244	                    .status(Xhq12Status.PENDING_PAYMENT)
   245	                    .build();
   246	
   247	            order = orderRepository.save(order);
   248	
   249	
   250	            paymentRequest.setOrderId(order.getId());
   251	            log.debug("결제 요청 정보: {}", paymentRequest);
   252	
   253	
   254	            try {
   255	                Xnd96 orderItem = orderItemCommandService.createOrderItem(order, saleBid.getProductSize(), saleBid.getBidPrice());
   256	                order.addOrderItem(orderItem);
   257	            } catch (Exception e) {
   258	                log.error("주문 항목 생성 중 오류 발생: {}", e.getMessage(), e);
   259	                throw new Xxx52Exception("주문 항목 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
   260	            }
   261	
   262	
   263	            try {
   264	                Xfr60 orderShipment = orderShipmentCommandService.createOrderShipment(
   265	                        order,
   266	                        address.getRecipientName(),
   267	                        address.getPhoneNumber(),
   268	                        address.getZipCode(),
   269	                        address.getAddress()
   270	                );
   271	                order.assignOrderShipment(orderShipment);
   272	            } catch (Exception e) {
   273	                log.error("배송 정보 생성 중 오류 발생: {}", e.getMessage(), e);
   274	                throw new Xjb41Exception("배송 정보 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
   275	            }
   276	
   277	            try {
   278	
   279	                saleBid.assignOrder(order);
   280	                saleBid.updateStatus(com.fream.back.domain.m85.entity.Xkh73Status.MATCHED);
   281	
   282	
   283	                entityManager.flush();
   284	            } catch (Exception e) {
   285	                log.error("판매 입찰 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
   286	                throw new Xfb77Exception("판매 입찰 매칭 중 오류가 발생했습니다: " + e.getMessage(), e);
   287	            }
   288	
   289	
   290	            try {
   291	                Xpj42 sale = saleBid.getSale();
   292	                if (sale != null && sale.isWarehouseStorage()) {
   293	                    warehouseStorageCommandService.updateWarehouseStatus(sale, Xbj62Status.ASSOCIATED_WITH_ORDER);
   294	                }
   295	            } catch (Xms75Exception e) {
   296	                log.error("창고 보관 상태 업데이트 중 오류 발생: {}", e.getMessage(), e);
   297	                throw new Xkd21Exception("창고 보관 상태 업데이트 중 오류가 발생했습니다: " + e.getMessage(), e);
   298	            } catch (Exception e) {
   299	                log.error("창고 보관 상태 업데이트 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
   300	                throw new Xkd21Exception("창고 보관 상태 업데이트 중 예상치 못한 오류가 발생했습니다: " + e.getMessage(), e);
   301	            }
   302	
   303	
   304	            try {
   305	                paymentCommandService.processPayment(order, buyer, paymentRequest);
   306	            } catch (Exception e) {
   307	                log.error("결제 처리 중 오류 발생: {}", e.getMessage(), e);
   308	                throw new Xwf42Exception("결제 처리 중 오류가 발생했습니다: " + e.getMessage(), e);
   309	            }
   310	
   311	            return order;
   312	        } catch (Exception e) {
   313	            if (e instanceof Xhq12Exception) {
   314	                throw e;
   315	            }
   316	            log.error("즉시 구매 주문 생성 중 오류 발생: {}", e.getMessage(), e);
   317	            throw new Xvq37Exception("즉시 구매 주문 생성 중 오류가 발생했습니다: " + e.getMessage(), e);
